  `kapasitas_maksimal` int unsigned NOT NULL DEFAULT '100',
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `archive_boxes_created_by_foreign` (`created_by`),
  KEY `archive_boxes_archive_type_id_nomor_box_index` (`archive_type_id`,`nomor_box`),
